from __future__ import annotations

import subprocess
from pathlib import Path
from typing import Any, Dict


def generate_demo_pcap(path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    sample = (
        "pcap placeholder\n"
        "This file is a placeholder generated by Auren Recon in demo mode.\n"
        "Replace it with a real BLE capture when running against an authorized target.\n"
    )
    path.write_text(sample, encoding="utf-8")
    return path


def run_capture(capture_config: Dict[str, Any], demo: bool = False) -> str:
    output_dir = Path(capture_config.get("output_dir", "./sessions"))
    output_dir.mkdir(parents=True, exist_ok=True)
    pcap_path = Path(capture_config.get("pcap_file", str(output_dir / "ble_capture.pcap")))
    pcap_path.parent.mkdir(parents=True, exist_ok=True)

    if demo:
        generate_demo_pcap(pcap_path)
        return str(pcap_path)

    commands = capture_config.get("commands", [])
    if not commands:
        generate_demo_pcap(pcap_path)
        return str(pcap_path)

    command_text = commands[0]
    try:
        subprocess.run(command_text, shell=True, check=True)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Capture command failed: {exc}") from exc

    if not pcap_path.exists():
        generate_demo_pcap(pcap_path)
    return str(pcap_path)
